import { isNullable } from './misc.ts'

/** Return true when every item in `array2` is present in `array1`. */
export function contain(array1: readonly any[], array2: readonly any[]) {
  return array2.every(item => array1.includes(item))
}

/** Return items that appear in both arrays. */
export function intersection<T>(array1: readonly T[], array2: readonly T[]) {
  return array1.filter(item => array2.includes(item))
}

/** Return items from `array1` that do not appear in `array2`. */
export function difference<S>(array1: readonly S[], array2: readonly any[]) {
  return array1.filter(item => !array2.includes(item))
}

/** Return the set-union of two arrays while preserving first occurrence order. */
export function union<T>(array1: readonly T[], array2: readonly T[]) {
  return Array.from(new Set([...array1, ...array2]))
}

/** Remove duplicate values while preserving first occurrence order. */
export function deduplicate<T>(array: readonly T[]) {
  return [...new Set(array)]
}

/** Remove one item from an array and report whether it was found. */
export function remove<T>(list: T[], item: T) {
  const index = list?.indexOf(item)
  if (index >= 0) {
    list.splice(index, 1)
    return true
  } else {
    return false
  }
}

/** Normalize nullish, scalar, or array input to an array. */
export function makeArray<T>(source: null | undefined | T | T[]) {
  return Array.isArray(source) ? source : isNullable(source) ? [] : [source]
}

// The same verifier is run against actual transpiled TS and actual compiled Mithril.
import assert from 'node:assert/strict';import vm from 'node:vm';import {pathToFileURL} from 'node:url';
async function verify(api,label){
let count=0;const pass=()=>count++;
const names=['contain','deduplicate','difference','intersection','makeArray','remove','union'];assert.deepEqual(Object.keys(api).sort(),names);
for(const name of names){assert.equal(api[name].name,name);assert.equal(api[name].length,['deduplicate','makeArray'].includes(name)?1:2);assert.equal(Object.hasOwn(api[name],'prototype'),true);}pass();
assert.equal(api.contain([1,2],[2]),true);assert.equal(api.contain([1],[2]),false);assert.equal(api.contain(null,[]),true);assert.equal(api.contain([NaN],[NaN]),true);pass();
assert.deepEqual(api.intersection([2,1,2,3],[2,3]),[2,2,3]);assert.deepEqual(api.difference([2,1,2,3],[2,3]),[1]);pass();
assert.deepEqual(api.intersection([,1,,2],[1,2]),[1,2]);assert.deepEqual(api.difference([,1,,2],[1]),[2]);assert.equal(api.contain(null,Array(3)),true);pass();
const object={},symbol=Symbol('item'),promise=Promise.resolve(1);assert.deepEqual(api.intersection([object,symbol,promise],[symbol,object]),[object,symbol]);assert.deepEqual(api.difference([object,symbol,promise],[symbol]),[object,promise]);pass();
assert.deepEqual(api.union([2,1,2],[1,3,2]),[2,1,3]);assert.deepEqual(api.deduplicate([2,1,2,3]),[2,1,3]);pass();
const zeros=api.union([-0,NaN,NaN],[0]);assert.equal(zeros.length,2);assert.ok(Object.is(zeros[0],0));assert.ok(Object.is(zeros[1],NaN));assert.deepEqual(api.deduplicate([object,object,symbol,symbol]),[object,symbol]);pass();
assert.deepEqual(api.union('ab','bc'),['a','b','c']);assert.deepEqual(api.deduplicate('aba'),['a','b']);assert.deepEqual(api.deduplicate(null),[]);assert.deepEqual(api.deduplicate(undefined),[]);pass();
for(const noniter of [null,undefined,1,{}])assert.throws(()=>api.union(noniter,[]),TypeError);for(const noniter of [1,{}])assert.throws(()=>api.deduplicate(noniter),TypeError);pass();
const sparse=[,1,,1];assert.deepEqual(api.union(sparse,[]),[undefined,1]);assert.deepEqual(api.deduplicate(sparse),[undefined,1]);pass();
let events=[];const right={*[Symbol.iterator](){events.push('right');yield 2}},left={*[Symbol.iterator](){events.push('left');yield 1}};assert.deepEqual(api.union(left,right),[1,2]);assert.deepEqual(events,['left','right']);pass();
const list=[1,2,1];assert.equal(api.remove(list,1),true);assert.deepEqual(list,[2,1]);assert.equal(api.remove(list,9),false);assert.deepEqual(list,[2,1]);assert.equal(api.remove([NaN],NaN),false);pass();
assert.equal(api.remove(null,object),false);assert.equal(api.remove(undefined,object),false);for(const v of [0,false,{}])assert.throws(()=>api.remove(v,object),TypeError);assert.equal(api.remove('',object),false);assert.throws(()=>api.remove('abc','a'),TypeError);pass();
events=[];const index={valueOf(){events.push('coerce');return 0}};
const custom={get indexOf(){events.push('lookup:indexOf');return function(item){assert.equal(this,custom);assert.equal(item,object);events.push('indexOf');return index}},get splice(){events.push('lookup:splice');return function(i,n){assert.equal(this,custom);assert.equal(i,index);assert.equal(n,1);assert.equal(arguments.length,2);events.push('splice');return promise}}};
assert.equal(api.remove(custom,object),true);assert.deepEqual(events,['lookup:indexOf','indexOf','coerce','lookup:splice','splice']);pass();
for(const value of [-1,undefined,NaN,'-1']){let invoked=false;assert.equal(api.remove({indexOf(){return value},splice(){invoked=true}},object),false);assert.equal(invoked,false);}for(const value of [null,'0',false,0n]){let indexSeen;assert.equal(api.remove({indexOf(){return value},splice(i){indexSeen=i}},object),true);assert.equal(indexSeen,value);}pass();
const boom={};assert.throws(()=>api.remove({get indexOf(){throw boom}},object),e=>e===boom);assert.throws(()=>api.remove({indexOf(){return {[Symbol.toPrimitive](){throw boom}}},splice(){throw Error('must not reach')}},object),e=>e===boom);assert.throws(()=>api.remove({indexOf(){return 0},splice(){throw boom}},object),e=>e===boom);pass();
for(const a of [[],[object],vm.runInNewContext('[]')])assert.equal(api.makeArray(a),a);for(const value of [0,false,'',symbol,object,promise,NaN])assert.deepEqual(api.makeArray(value),[value]);assert.deepEqual(api.makeArray(null),[]);assert.deepEqual(api.makeArray(undefined),[]);assert.notEqual(api.makeArray(null),api.makeArray(null));pass();
const arrayProxy=new Proxy([],{get(){throw boom},getPrototypeOf(){throw boom}});assert.equal(api.makeArray(arrayProxy),arrayProxy);const opaque=new Proxy({},{get(){throw boom},getPrototypeOf(){throw boom}});assert.deepEqual(api.makeArray(opaque),[opaque]);const rev=Proxy.revocable([],{});rev.revoke();assert.throws(()=>api.makeArray(rev.proxy),TypeError);pass();
let callback;const context={includes(v){assert.equal(this,context);return v===object}};const second={every(fn){assert.equal(this,second);callback=fn;assert.equal(fn.name,'');assert.equal(fn.length,1);assert.equal(Object.hasOwn(fn,'prototype'),false);return promise}};
assert.equal(api.contain(context,second),promise);assert.equal(callback(object),true);assert.equal(callback(symbol),false);assert.throws(()=>Reflect.construct(callback,[object]),TypeError);pass();
let captured;const first={filter(fn){assert.equal(this,first);captured=fn;return promise}};assert.equal(api.intersection(first,context),promise);assert.equal(captured(object),true);assert.equal(captured(symbol),false);assert.equal(api.difference(first,context),promise);assert.equal(captured(object),false);assert.equal(captured(symbol),true);pass();
for(const value of [null,undefined]){assert.throws(()=>api.contain([],value),TypeError);assert.throws(()=>api.intersection(value,[]),TypeError);assert.throws(()=>api.difference(value,[]),TypeError);}assert.deepEqual(api.intersection([],null),[]);assert.deepEqual(api.difference([],null),[]);assert.throws(()=>api.intersection([1],null),TypeError);pass();
let gets=0;const eagerStop={get 0(){gets++;return 9},get 1(){throw boom},length:2,every:Array.prototype.every};assert.equal(api.contain([],eagerStop),false);assert.equal(gets,1);pass();
const from=Object.getOwnPropertyDescriptor(Array,'from'),set=Object.getOwnPropertyDescriptor(globalThis,'Set');events=[];const SetOriginal=set.value;
try{Object.defineProperty(Array,'from',{configurable:true,get(){events.push('from:lookup');return function(iter){assert.equal(this,Array);events.push('from:call');return from.value.call(this,iter)}}});Object.defineProperty(globalThis,'Set',{configurable:true,get(){events.push('Set:lookup');return function(iter){events.push('Set:construct');return new SetOriginal(iter)}}});const one={*[Symbol.iterator](){events.push('iterate:one');yield 1}},two={*[Symbol.iterator](){events.push('iterate:two');yield 2}};assert.deepEqual(api.union(one,two),[1,2]);assert.deepEqual(events,['from:lookup','Set:lookup','iterate:one','iterate:two','Set:construct','from:call']);}finally{Reflect.defineProperty(Array,'from',from);Reflect.defineProperty(globalThis,'Set',set);}pass();
let replacementCalled=false;try{const replacing={*[Symbol.iterator](){globalThis.Set=function(){replacementCalled=true;throw boom};yield 1}};assert.deepEqual(api.union(replacing,[]),[1]);assert.equal(replacementCalled,false);}finally{Reflect.defineProperty(globalThis,'Set',set);}pass();
try{const marker={};Array.from=function(){assert.equal(this,Array);return marker};assert.equal(api.union([],[]),marker);}finally{Reflect.defineProperty(Array,'from',from);}pass();
try{globalThis.Set=function(){return {[Symbol.iterator](){return ['custom',object][Symbol.iterator]()}}};assert.deepEqual(api.deduplicate([1,1]),['custom',object]);}finally{Reflect.defineProperty(globalThis,'Set',set);}pass();
const isArray=Object.getOwnPropertyDescriptor(Array,'isArray');events=[];try{Object.defineProperty(Array,'isArray',{configurable:true,get(){events.push('get');return function(v){assert.equal(this,Array);events.push('call');return v===object}}});assert.equal(api.makeArray(object),object);assert.deepEqual(events,['get','call']);}finally{Reflect.defineProperty(Array,'isArray',isArray);}pass();
assert.deepEqual(Reflect.construct(api.union,[[1],[2]]),[1,2]);assert.deepEqual(Reflect.construct(api.makeArray,[object]),[object]);const instance=Reflect.construct(api.contain,[[],[]]);assert.equal(Object.getPrototypeOf(instance),api.contain.prototype);pass();
let consumed=0;const failed={*[Symbol.iterator](){consumed++;throw boom}};assert.throws(()=>api.union(failed,[]),e=>e===boom);assert.equal(consumed,1);assert.throws(()=>api.deduplicate(failed),e=>e===boom);pass();
for(let i=0;i<2000;i++){assert.deepEqual(api.union([object],[symbol]),[object,symbol]);assert.equal(api.makeArray(arrayProxy),arrayProxy);}pass();
assert.equal(count,30);console.log(label+': 30 complete array runtime contract groups passed.');
}
const baseline=await import('./array-baseline.mjs');await verify(baseline,'actual TypeScript array baseline');
if(process.argv[2]){if(!process.argv[3])throw Error('actual compiled Mithril misc dependency required');const misc=(await import(pathToFileURL(process.argv[3]).href)).instantiateMithrilNative({get Object(){return globalThis.Object},get Array(){return globalThis.Array},get Reflect(){return globalThis.Reflect}});const native=await import(pathToFileURL(process.argv[2]).href);const api=native.instantiateMithrilNative({get Array(){return globalThis.Array},get Set(){return globalThis.Set},get isNullable(){return misc.isNullable}});await verify(api,'Mithril array candidate linked to generated Mithril misc');}
